package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.mock;
import com.lianxibu.site.config.*;import com.lianxibu.site.controller.collector.*;import com.lianxibu.site.domain.protocol.CanonicalJson;import com.lianxibu.site.service.identity.NodeIdentityService;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.springframework.boot.autoconfigure.EnableAutoConfiguration;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.context.annotation.Import;import org.springframework.context.support.GenericApplicationContext;
class CollectorHeartbeatHttpTest {
 @org.springframework.boot.test.context.TestConfiguration(proxyBeanMethods=false)
 @EnableAutoConfiguration(exclude=org.springframework.boot.jdbc.autoconfigure.DataSourceAutoConfiguration.class)
 @Import({CollectorController.class,CollectorSecurityConfiguration.class,BootstrapSecurityConfiguration.class}) static class App{}
 CollectorHeartbeatServiceTest f;org.springframework.context.ConfigurableApplicationContext app;HttpClient client;String root;
 CollectorHeartbeatService heartbeatService(){return f.service;}
 DataSource source(){return new CollectorHeartbeatServiceTest().source();}
 @BeforeEach void setup()throws Exception{f=new CollectorHeartbeatServiceTest(){@Override DataSource source(){return CollectorHeartbeatHttpTest.this.source();}};f.setup();start(false);client=HttpClient.newHttpClient();}
 void start(boolean legacy){app=new SpringApplicationBuilder(App.class).properties("server.port=0","server.address=127.0.0.1","spring.main.banner-mode=off","logging.level.root=ERROR").initializers(context->{var registry=(GenericApplicationContext)context;registry.registerBean(NodeIdentityService.class,()->f.identity);registry.registerBean(CollectorGateway.class,()->{var leases=mock(com.lianxibu.site.service.sources.SourceRunLeaseService.class);var manifests=mock(com.lianxibu.site.service.sources.RunManifestService.class);var observations=mock(com.lianxibu.site.service.articles.ObservationIngressService.class);var probes=mock(com.lianxibu.site.service.sources.ProbeResultService.class);return legacy?new JdbcCollectorGateway(f.f.db,f.identity,leases,manifests,observations,probes,f.clock):new JdbcCollectorGateway(f.f.db,f.identity,leases,manifests,observations,probes,f.clock,heartbeatService());});}).run("--site.collector.enabled=true");root="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort()+"/api/collector/v1/heartbeat";}
 @AfterEach void cleanup(){if(client!=null)client.close();if(app!=null)app.close();if(f!=null)f.cleanup();}
 HttpResponse<String> post(String token,String suffix,byte[] raw,boolean extra)throws Exception{var request=HttpRequest.newBuilder(URI.create(root+suffix)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofByteArray(raw));if(token!=null)request.header("Authorization","Bearer "+token);if(extra)request.header("Idempotency-Key","fictional-unused-key");return client.send(request.build(),HttpResponse.BodyHandlers.ofString());}
 void code(HttpResponse<String> response,int status,String code){assertEquals(status,response.statusCode(),response.body());assertEquals(code,CanonicalJson.parse(response.body()).at("/error/code").asText());assertEquals("no-store",response.headers().firstValue("Cache-Control").orElseThrow());}
 @Test void realHttpCurrentBearerNativeWriterAndOriginalAckThenRevocation()throws Exception{var raw=f.raw(f.f.now,10);code(post(null,"",raw,false),401,"unauthenticated");code(post("B".repeat(43),"",raw,false),403,"forbidden");var first=post(f.token,"",raw,false);assertEquals(200,first.statusCode(),first.body());var data=CanonicalJson.parse(first.body()).get("data");assertEquals(1,data.size());assertEquals("2026-01-01T00:10:00.000000Z",data.get("received_at").asText());f.at.set(f.f.now.plusSeconds(600));assertEquals(data,CanonicalJson.parse(post(f.token,"",raw,false).body()).get("data"));assertEquals(1L,f.f.tx.execute(s->f.f.store.latest(f.f.node,1)).revision());assertEquals(1,f.nodes.revoke(f.f.node,1));code(post(f.token,"",raw,false),403,"forbidden");}
 @Test void originalClosedFieldsQueryDuplicatesRawCapacityAndIncompleteQueueAreRejected()throws Exception{var raw=f.raw(f.f.now,10);code(post(f.token,"?unexpected=1",raw,false),400,"protocol_error");code(post(f.token,"",raw,true),400,"protocol_error");var text=new String(raw,StandardCharsets.UTF_8);code(post(f.token,"",text.replace("{","{\"rss_bytes\":0,").getBytes(StandardCharsets.UTF_8),false),400,"protocol_error");code(post(f.token,"",text.replace("{","{\"quarantined\":0,").getBytes(StandardCharsets.UTF_8),false),400,"protocol_error");code(post(f.token,"",text.replace("\"pending_controls\":0","\"pending_controls\":1").getBytes(StandardCharsets.UTF_8),false),422,"validation");code(post(f.token,"",new byte[4097],false),413,"payload_too_large");assertNull(f.f.tx.execute(s->f.f.store.latest(f.f.node,1)));}
 @Test void nativeDamageStaleOrFutureNeverReturnsSuccessfulReceiptOrLeaksPrivateStorage()throws Exception{code(post(f.token,"",f.raw(f.f.now.plusSeconds(1),10),false),422,"validation");assertEquals(200,post(f.token,"",f.raw(f.f.now,10),false).statusCode());f.f.jdbc.update("UPDATE runtime_settings SET revision=0 WHERE setting_key=?",com.lianxibu.site.repository.jobs.JdbcCollectorHeartbeats.key(f.f.node));var result=post(f.token,"",f.raw(f.f.now,10),false);code(result,503,"temporarily_unavailable");assertEquals("1",result.headers().firstValue("Retry-After").orElseThrow());assertFalse(result.body().contains("SELECT"));assertFalse(result.body().contains(f.token));assertFalse(result.body().contains("heartbeat proof"));}
 @Test void missingPersistenceProviderFailsClosedThroughOriginalHttpWithoutInventedReceivedTime()throws Exception{app.close();start(true);code(post(f.token,"",f.raw(f.f.now,10),false),503,"temporarily_unavailable");assertNull(f.f.tx.execute(s->f.f.store.latest(f.f.node,1)));}
}
